        local name = string(nameof(type_))
        isempty(type_.parameters) && return name
        return "$name<$(join((t isa Union{Type,TypeVar} ? _name_type(self, t) : "$t" for t in type_.parameters), ", "))>"
    end
    return "$type_"
end
